const assets = {"/":["\r\n<!doctype html>\r\n<html lang=\"es\">\r\n<head>\r\n  <meta charset=\"utf-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n  <meta name=\"description\" content=\"Encuentra el próximo paso y la fuente oficial para servicios de Miami y Miami Gardens.\">\r\n  <title>AskMyCity · Miami & Miami Gardens</title>\r\n  <link rel=\"stylesheet\" href=\"/style.css\">\r\n  <script type=\"module\" src=\"/app.js\"></script>\r\n</head>\r\n<body>\r\n  <header>\r\n    <div class=\"bar\">\r\n      <div class=\"brand\"><span class=\"logo\" aria-hidden=\"true\">A</span> AskMyCity</div>\r\n      <label class=\"language\"><span id=\"lang-label\">Idioma</span>\r\n        <select id=\"language\">\r\n          <option value=\"es\">Español</option><option value=\"en\">English</option><option value=\"ht\">Kreyòl ayisyen</option>\r\n        </select>\r\n      </label>\r\n    </div>\r\n  </header>\r\n  <main>\r\n    <section class=\"intro\" aria-labelledby=\"heading\">\r\n      <p class=\"eyebrow\">MIAMI / MIAMI GARDENS</p>\r\n      <h1 id=\"heading\">¿En qué te puede<br>ayudar tu ciudad?</h1>\r\n      <p id=\"intro\">Cuenta qué necesitas. Encuentra un próximo paso y la fuente oficial.</p>\r\n    </section>\r\n    <section class=\"panel\">\r\n      <form id=\"form\">\r\n        <div class=\"field\"><label for=\"city\" id=\"city-label\">Elige tu ciudad</label>\r\n          <select id=\"city\"><option value=\"miami\">City of Miami</option><option value=\"gardens\">Miami Gardens</option></select>\r\n        </div>\r\n        <div class=\"field\"><label for=\"question\" id=\"question-label\">¿Qué necesitas?</label>\r\n          <textarea id=\"question\" rows=\"3\" maxlength=\"400\" required placeholder=\"No puedo pagar la renta\"></textarea>\r\n        </div>\r\n        <button id=\"example\" type=\"button\" class=\"chip\"></button>\r\n        <div class=\"buttons\">\r\n          <button id=\"submit\" type=\"submit\">Buscar ayuda <span aria-hidden=\"true\">↗️</span></button>\r\n          <button id=\"mic\" type=\"button\" class=\"outline\" hidden>Dictar pregunta</button>\r\n        </div>\r\n        <p id=\"privacy\" class=\"note\">Escribe tu pregunta sin nombres, direcciones ni números personales.</p>\r\n      </form>\r\n      <p id=\"message\" role=\"status\"></p>\r\n    </section>\r\n    <article id=\"answer\" class=\"answer\" hidden tabindex=\"-1\" aria-labelledby=\"answer-title\">\r\n      <p id=\"answer-status\" class=\"eyebrow\"></p>\r\n      <h2 id=\"answer-title\"></h2>\r\n      <p id=\"summary\"></p>\r\n      <div class=\"step\"><strong id=\"step-label\">Tu próximo paso</strong><p id=\"step\"></p></div>\r\n      <div class=\"buttons\">\r\n        <a id=\"source\" class=\"outline\" target=\"_blank\" rel=\"noopener noreferrer\"></a>\r\n        <a id=\"phone\" class=\"outline\"></a>\r\n        <button id=\"audio\" class=\"outline\" type=\"button\" hidden></button>\r\n      </div>\r\n      <p class=\"note\" id=\"verified\"></p>\r\n    </article>\r\n    <footer><span>AskMyCity · SharkByte 2026</span><span id=\"footer\">Proyecto estudiantil independiente</span></footer>\r\n  </main>\r\n</body>\r\n</html>\r\n","text/html"],"/style.css":["\r\n:root { color-scheme: light; --ink:#0b302c; --muted:#41635d; --paper:#f1f6ef; --line:#afc8bf; --mint:#daf0dc; --green:#115346; }\r\n* { box-sizing:border-box; }\r\n[hidden] { display:none !important; }\r\nbody { margin:0; background:radial-gradient(ellipse at 80% 5%,#ddf1db,transparent 37rem),var(--paper); color:var(--ink); font:16px/1.55 system-ui,sans-serif; }\r\nheader { border-bottom:1px solid var(--line); }\r\n.bar { max-width:1024px; margin:auto; padding:16px clamp(14px,4vw,32px); display:flex; align-items:center; justify-content:space-between; gap:12px; }\r\n.brand { font-weight:850; font-size:1.13rem; display:flex; align-items:center; gap:9px; }\r\n.logo { display:grid; place-items:center; width:35px; height:35px; background:var(--green); border-radius:12px 12px 12px 4px; color:#fff; }\r\n.language { display:flex; align-items:center; gap:8px; font-weight:650; }\r\nmain { max-width:760px; margin:auto; padding:clamp(26px,5vw,54px) clamp(14px,4vw,32px) 0; }\r\n.eyebrow { font-size:.76rem; font-weight:850; letter-spacing:.16em; color:var(--green); margin:0 0 12px; }\r\nh1 { font-size:clamp(2.4rem,7vw,4.9rem); line-height:1.02; letter-spacing:-.06em; margin:0; font-weight:840; }\r\nh2 { font-size:clamp(1.5rem,4vw,2.1rem); line-height:1.15; margin:0; letter-spacing:-.035em; }\r\n.intro > p:last-child { font-size:clamp(1rem,3vw,1.22rem); color:var(--muted); margin:14px 0 25px; }\r\n.panel,.answer { background:#fff; border:1px solid var(--line); padding:clamp(17px,4vw,28px); border-radius:22px; box-shadow:0 10px 30px #103e3010; }\r\n.answer { margin-top:18px; }\r\n.field { display:grid; gap:6px; margin-bottom:13px; }\r\nlabel { font-weight:750; }\r\nbutton,a,select,textarea { font:inherit; }\r\nselect,textarea { color:var(--ink); background:#f9fcf8; border:1px solid #8aaba1; border-radius:9px; padding:9px 11px; }\r\ntextarea { display:block; resize:vertical; min-height:82px; }\r\nbutton,.outline { min-height:44px; padding:8px 15px; border:1px solid var(--green); border-radius:9px; color:#fff; background:var(--green); cursor:pointer; font-weight:750; text-decoration:none; display:inline-flex; gap:10px; align-items:center; }\r\nbutton:disabled { opacity:.65; cursor:wait; }\r\nbutton:hover:not(:disabled) { filter:brightness(.93); }\r\n.outline,.chip { color:var(--green); background:#f3f9f2; }\r\n.chip { border-style:dashed; min-height:44px; padding:5px 11px; font-size:.9rem; text-align:left; }\r\n.buttons { display:flex; align-items:center; flex-wrap:wrap; gap:8px; margin-top:13px; }\r\n:focus-visible { outline:3px solid #2479aa; outline-offset:3px; }\r\n.step { background:var(--mint); border-left:4px solid var(--green); border-radius:8px; padding:12px 15px; }\r\n.step p { margin:4px 0 0; }\r\n.note,footer { color:var(--muted); font-size:.87rem; }\r\n#demo-wrap { display:flex; align-items:center; gap:8px; margin-top:10px; }\r\n#message:empty { display:none; }\r\n#message,.note { margin-bottom:0; }\r\nfooter { display:flex; flex-wrap:wrap; gap:10px 24px; justify-content:space-between; margin-top:25px; padding:15px 0 22px; border-top:1px solid var(--line); }\r\n@media (max-width:440px) { .language span { position:absolute; width:1px; height:1px; clip-path:inset(50%); } }\r\n","text/css"],"/app.js":["\r\nconst byId = (id) => document.getElementById(id);\r\nconst city = byId('city');\r\nconst language = byId('language');\r\nconst question = byId('question');\r\nconst form = byId('form');\r\nconst answer = byId('answer');\r\nconst mic = byId('mic');\r\nconst audio = byId('audio');\r\nconst speech = window.speechSynthesis;\r\nconst SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;\r\nconst locales = { es: 'es-US', en: 'en-US', ht: 'ht-HT' };\r\nconst copy = {\r\n  es: {\r\n    'lang-label': 'Idioma', heading: '¿En qué te puede ayudar tu ciudad?',\r\n    intro: 'Cuenta qué necesitas. Encuentra un próximo paso y la fuente oficial.',\r\n    'city-label': 'Elige tu ciudad', 'question-label': '¿Qué necesitas?', submit: 'Buscar ayuda ↗️',\r\n    mic: 'Dictar pregunta', audio: 'Escuchar', 'step-label': 'Tu próximo paso',\r\n    source: 'Abrir fuente oficial ↗️', footer: 'Proyecto estudiantil independiente',\r\n    privacy: 'Escribe tu pregunta sin nombres, direcciones ni números personales.',\r\n    example: 'Ejemplo',\r\n    examples: { miami: 'No puedo pagar la renta', gardens: 'Busco trabajo' },\r\n    status: { verified: 'RECURSO OFICIAL', unverified: 'COBERTURA LIMITADA', emergency: 'EMERGENCIA' },\r\n    checked: 'Fuente revisada', loading: 'Buscando…', error: 'No pudimos conectar. Inténtalo de nuevo.',\r\n    micError: 'El dictado no está disponible. Puedes escribir tu pregunta.', listening: 'Escuchando…',\r\n    voiceError: 'No hay una voz compatible para este idioma.',\r\n  },\r\n  en: {\r\n    'lang-label': 'Language', heading: 'How can your city help?',\r\n    intro: 'Tell us what you need. Find a next step and the official source.',\r\n    'city-label': 'Choose your city', 'question-label': 'What do you need?', submit: 'Find help ↗️',\r\n    mic: 'Dictate question', audio: 'Listen', 'step-label': 'Your next step',\r\n    source: 'Open official source ↗️', footer: 'Independent student project',\r\n    privacy: 'Leave out names, addresses and personal numbers.',\r\n    example: 'Example',\r\n    examples: { miami: 'I cannot pay rent', gardens: 'I am looking for a job' },\r\n    status: { verified: 'OFFICIAL RESOURCE', unverified: 'LIMITED COVERAGE', emergency: 'EMERGENCY' },\r\n    checked: 'Source reviewed', loading: 'Searching…', error: 'Could not connect. Please try again.',\r\n    micError: 'Dictation is unavailable. You can type your question.', listening: 'Listening…',\r\n    voiceError: 'No compatible voice is available for this language.',\r\n  },\r\n  ht: {\r\n    'lang-label': 'Lang', heading: 'Ki jan vil ou a ka ede w?',\r\n    intro: 'Di nou sa w bezwen. Jwenn yon pwochen etap ak sous ofisyèl la.',\r\n    'city-label': 'Chwazi vil ou', 'question-label': 'Ki sa w bezwen?', submit: 'Chèche èd ↗️',\r\n    mic: 'Dikte kesyon an', audio: 'Koute', 'step-label': 'Pwochen etap ou',\r\n    source: 'Louvri sous ofisyèl la ↗️', footer: 'Pwojè etidyan endepandan',\r\n    privacy: 'Pa mete non, adrès ni nimewo pèsonèl.',\r\n    example: 'Egzanp',\r\n    examples: { miami: 'Mwen pa ka peye lwaye', gardens: 'M ap chèche travay' },\r\n    status: { verified: 'RESOUS OFISYÈL', unverified: 'KOUVÈTI LIMITE', emergency: 'IJANS' },\r\n    checked: 'Dat verifikasyon sous la', loading: 'N ap chèche…', error: 'Koneksyon an pa mache. Eseye ankò.',\r\n    micError: 'Dikte pa disponib. Ou ka ekri kesyon an.', listening: 'N ap koute…',\r\n    voiceError: 'Pa gen vwa ki disponib pou lang sa a.',\r\n  },\r\n};\r\nlet pending;\r\nlet recognition;\r\nconst current = () => copy[language.value];\r\nconst example = () => current().examples[city.value];\r\nconst message = (text) => { byId('message').textContent = text; };\r\n\r\nfunction reset() {\r\n  pending?.abort();\r\n  recognition?.abort();\r\n  recognition = undefined;\r\n  mic.disabled = false;\r\n  byId('submit').disabled = false;\r\n  answer.hidden = true;\r\n  speech?.cancel();\r\n  message('');\r\n}\r\n\r\nfunction localize() {\r\n  reset();\r\n  const text = current();\r\n  document.documentElement.lang = language.value;\r\n  for (const id of ['lang-label', 'heading', 'intro', 'city-label', 'question-label', 'submit', 'mic',\r\n    'audio', 'step-label', 'source', 'footer', 'privacy']) byId(id).textContent = text[id];\r\n  question.placeholder = example();\r\n  byId('example').textContent = text.example + ' · ' + example();\r\n  mic.hidden = !SpeechRecognition;\r\n}\r\n\r\ncity.addEventListener('change', localize);\r\nlanguage.addEventListener('change', localize);\r\nquestion.addEventListener('input', reset);\r\nbyId('example').addEventListener('click', () => {\r\n  reset();\r\n  question.value = example();\r\n  question.focus();\r\n});\r\n\r\nmic.addEventListener('click', () => {\r\n  const instance = new SpeechRecognition();\r\n  recognition = instance;\r\n  instance.lang = locales[language.value];\r\n  instance.onresult = ({ results }) => {\r\n    if (instance !== recognition) return;\r\n    question.value = results[0][0].transcript.slice(0, 400);\r\n    message('');\r\n  };\r\n  instance.onerror = () => { if (instance === recognition) message(current().micError); };\r\n  instance.onend = () => {\r\n    if (instance !== recognition) return;\r\n    mic.disabled = false;\r\n    if (byId('message').textContent === current().listening) message('');\r\n  };\r\n  try {\r\n    instance.start();\r\n    mic.disabled = true;\r\n    message(current().listening);\r\n  } catch {\r\n    message(current().micError);\r\n  }\r\n});\r\n\r\naudio.addEventListener('click', () => {\r\n  const prefix = language.value + '-';\r\n  const voice = speech.getVoices().find((item) => item.lang.toLowerCase().startsWith(prefix));\r\n  if (!voice && language.value === 'ht') {\r\n    byId('verified').textContent += ' · ' + current().voiceError;\r\n    audio.disabled = true;\r\n    return;\r\n  }\r\n  speech.cancel();\r\n  const utterance = new SpeechSynthesisUtterance(byId('summary').textContent + ' ' + byId('step').textContent);\r\n  utterance.lang = locales[language.value];\r\n  if (voice) utterance.voice = voice;\r\n  speech.speak(utterance);\r\n});\r\n\r\nform.addEventListener('submit', async (event) => {\r\n  event.preventDefault();\r\n  reset();\r\n  const controller = new AbortController();\r\n  pending = controller;\r\n  const submit = byId('submit');\r\n  submit.disabled = true;\r\n  message(current().loading);\r\n  try {\r\n    const response = await fetch('/api/ask', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      signal: controller.signal,\r\n      body: JSON.stringify({ city: city.value, language: language.value, question: question.value }),\r\n    });\r\n    if (!response.ok) throw new Error('Request failed');\r\n    const result = await response.json();\r\n    if (controller.signal.aborted) return;\r\n    const text = current();\r\n    byId('answer-status').textContent = text.status[result.status];\r\n    byId('answer-title').textContent = result.title;\r\n    byId('summary').textContent = result.summary;\r\n    byId('step').textContent = result.nextStep;\r\n    byId('source').href = result.source.url;\r\n    byId('phone').href = 'tel:' + result.source.phone;\r\n    byId('phone').textContent = result.source.phone;\r\n    byId('verified').textContent = result.source.checked ? text.checked + ' · ' + result.source.checked : '';\r\n    audio.hidden = !speech || !window.SpeechSynthesisUtterance;\r\n    audio.disabled = false;\r\n    message('');\r\n    answer.hidden = false;\r\n    answer.focus();\r\n  } catch {\r\n    if (!controller.signal.aborted) message(current().error);\r\n  } finally {\r\n    if (pending === controller) {\r\n      pending = undefined;\r\n      submit.disabled = false;\r\n    }\r\n  }\r\n});\r\n\r\nlocalize();\r\n","text/javascript"]};

const contacts = {
  miami: { url: 'https://www.miami.gov/My-Home-Neighborhood/Solve-a-Problem', phone: '311' },
  gardens: { url: 'https://www.miamigardens-fl.gov/244/Resident-Services', phone: '305-622-8000' },
};
const languages = new Set(['es', 'en', 'ht']);
const emergency = { url: 'https://www.miamidade.gov/global/police/contact-police.page', phone: '911' };
const emergencyTerms = /\b(911|emergencia|emergency|danje touswit|peligro inmediato|immediate danger|hay (?:un )?incendio|is injured|no respira|not breathing|pa respire)\b/;
const unsupported = /\b(pasaporte|passport|votar|vote|eleccion(?:es)?|election(?:s)?|ballot|kandida|ignore|ignora|olvida|system prompt|instrucciones (?:previas|anteriores))\b/;
const outsideCities = /\b(miami beach|north miami(?: beach)?|hialeah|doral|coral gables|kendall|opa locka|homestead)\b/;
const fallbackCopy = {
  es: ['Consulta con tu ciudad', 'El directorio aún no tiene una respuesta verificada para esta pregunta.', 'Llama al número oficial para pedir orientación.'],
  en: ['Check with your city', 'The directory does not have a verified answer for this question yet.', 'Call the official number for guidance.'],
  ht: ['Mande vil ou a', 'Anyè a poko gen yon repons verifye pou kesyon sa a.', 'Rele nimewo ofisyèl la pou jwenn èd.'],
};
const emergencyCopy = {
  es: ['Emergencia', 'Si hay peligro inmediato, usa la línea de emergencias.', 'Llama al 911.'],
  en: ['Emergency', 'If there is immediate danger, use the emergency line.', 'Call 911.'],
  ht: ['Ijans', 'Si gen danje touswit, sèvi ak liy ijans lan.', 'Rele 911.'],
};
const examples = {
  miami: { es: 'No puedo pagar la renta', en: 'I cannot pay rent', ht: 'Mwen pa ka peye lwaye' },
  gardens: { es: 'Busco trabajo', en: 'I am looking for a job', ht: 'M ap chèche travay' },
};
export const sponsorParaphrases = [
  { city: 'miami', language: 'es', question: 'el agua no baja por la alcantarilla', id: 'flood' },
  { city: 'miami', language: 'en', question: 'the road in front of my house has a big hole', id: 'pothole' },
  { city: 'miami', language: 'es', question: 'el pasto del terreno vacío está altísimo', id: 'overgrown' },
  { city: 'miami', language: 'ht', question: 'gen fatra moun jete sou teren vid la', id: 'dumping' },
];
const safetyHeaders = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'Content-Security-Policy': "default-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'",
};
const normalize = (value) => value.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const json = (value, status = 200) => Response.json(value, {
  status,
  headers: { ...safetyHeaders, 'Cache-Control': 'no-store' },
});

function pickResource(question, city) {
  const normalized = normalize(question);
  if (unsupported.test(normalized) || outsideCities.test(normalized)) return;
  const withoutGardens = normalized.replace(/\b(?:city of )?miami gardens\b/g, '');
  if (city === 'miami' && withoutGardens !== normalized) return;
  if (city === 'gardens' && /\b(?:city of miami|ciudad de miami)\b/.test(withoutGardens)) return;
  const padded = ' ' + normalized + ' ';
  const matches = resources.filter((resource) =>
    resource.city === city && resource.terms.some((term) => padded.includes(' ' + term + ' ')));
  if (matches.length === 1) return matches[0];
  if (matches.length !== 2) return;

  const generalRent = matches.find(({ id }) => id === 'rent');
  const specificRent = matches.find(({ id }) => id === 'senior-rent' || id === 'section8');
  if (!generalRent || !specificRent) return;
  // A program name can contain a general housing term. Separate requests remain ambiguous.
  const remainder = specificRent.terms.reduce((text, term) => text.replaceAll(' ' + term + ' ', ' '), padded);
  if (!generalRent.terms.some((term) => remainder.includes(' ' + term + ' '))) return specificRent;
}

function card(resource, copy, status, routing) {
  const [title, summary, nextStep] = copy;
  return { status, title, summary, nextStep, routing, source: {
    id: resource.id, url: resource.url, phone: resource.phone, checked: resource.checked,
  } };
}

async function requestProvider(url, headers, body, timeout) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...headers },
    signal: AbortSignal.timeout(timeout),
    redirect: 'manual',
    body: JSON.stringify(body),
  });
  if (!response.ok) throw new Error('Provider HTTP ' + response.status);
  return response.json();
}

function answerText(output) {
  if (typeof output === 'string') return output.trim();
  if (Array.isArray(output)) return answerText(output.findLast((entry) => entry?.role === 'assistant'));
  if (output && typeof output.content === 'string') return output.content.trim();
  return '';
}

function sponsorsConfigured(env) {
  return Boolean(env.SPONSOR_DEMO_TOKEN && env.SWARMS_API_KEY && env.PRUNE_API_KEY);
}

function sponsorsAuthorized(request, env) {
  return sponsorsConfigured(env) &&
    request.headers.get('Authorization') === 'Bearer ' + env.SPONSOR_DEMO_TOKEN;
}

export async function runSwarms(city, language, env, question = examples[city][language]) {
  const candidates = resources.filter((entry) => entry.city === city);
  const task = JSON.stringify({
    question,
    candidates: candidates.map(({ id, copy }) => ({ id, description: copy[language][1] })),
  });
  const sequential = env.SWARMS_WORKFLOW === 'sequential';
  const endpoint = sequential ? 'swarm' : 'graph-workflow';
  const result = await requestProvider('https://api.swarms.world/v1/' + endpoint + '/completions',
    { 'x-api-key': env.SWARMS_API_KEY }, {
      name: 'AskMyCity civic resource demo',
      description: 'Select and check a catalog ID for an approved public example.',
      task,
      agents: [
        { agent_name: 'Router', system_prompt: 'Select the best matching candidate. Output only its exact ID or NONE.' },
        { agent_name: 'Evidence', system_prompt: 'Check the selected ID against the original task and descriptions. Return only the exact matching ID or NONE.' },
      ].map((agent) => ({ ...agent, model_name: env.SWARMS_MODEL || 'gpt-5.4-mini', max_loops: 1, max_tokens: 120 })),
      ...(sequential ? { swarm_type: 'SequentialWorkflow' } : {
        edges: [{ source: 'Router', target: 'Evidence' }],
        entry_points: ['Router'],
        end_points: ['Evidence'],
      }),
      max_loops: 1,
    }, 30000);
  let evidence = result.outputs?.Evidence;
  if (sequential) {
    evidence = result.status === 'success' && Array.isArray(result.output)
      ? result.output.findLast((message) => message?.role === 'Evidence')
      : undefined;
  }
  return { id: answerText(evidence), cost: result.usage?.total_cost };
}

async function runSponsors(resource, city, language, question, env) {
  const routing = { swarms: 'unavailable', prune: 'unavailable' };
  try {
    const swarms = await runSwarms(city, language, env, question);
    if (swarms.id !== resource.id) {
      routing.swarms = 'rejected';
      return routing;
    }
    routing.swarms = 'verified';
    if (Number.isFinite(swarms.cost)) routing.swarmsCost = swarms.cost;
  } catch {
    return routing;
  }
  try {
    const prune = await requestProvider('https://api.withprune.com/v1/chat/completions',
      { Authorization: 'Bearer ' + env.PRUNE_API_KEY }, {
        model: env.PRUNE_MODEL || 'gpt-4o-mini',
        max_tokens: 64,
        messages: [
          { role: 'user', content: 'Check if the official resource is relevant to the example question. Output exactly YES or NO.\n' + JSON.stringify({ question, officialResource: resource.copy[language] }) },
        ],
      }, 45000);
    const verified = answerText(prune.choices?.[0]?.message) === 'YES';
    const signature = prune.prune_metadata?.receipt_signature;
    const hasReceipt = typeof signature === 'string' && signature.trim().length > 0;
    routing.prune = verified && hasReceipt ? 'verified' : 'rejected';
    if (hasReceipt) routing.pruneReceipt = true;
  } catch {
    // The official card remains available when a provider fails.
  }
  return routing;
}

async function readQuestion(request) {
  const reader = request.body?.getReader();
  if (!reader) return;
  const decoder = new TextDecoder();
  let length = 0;
  let body = '';
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    length += value.byteLength;
    if (length > 4096) {
      await reader.cancel();
      return;
    }
    body += decoder.decode(value, { stream: true });
  }
  try {
    return JSON.parse(body + decoder.decode());
  } catch {
    return;
  }
}

async function ask(request, env) {
  if (!/^application\/json(?:\s*;|$)/i.test(request.headers.get('Content-Type') || '')) {
    return json({ error: 'expected_json' }, 415);
  }
  const payload = await readQuestion(request);
  const { question, city, language, demo } = payload || {};
  if (typeof city !== 'string' || !Object.hasOwn(contacts, city) || !languages.has(language) ||
      typeof question !== 'string' || !question.trim() || question.length > 400) {
    return json({ error: 'invalid_question_city_or_language' }, 400);
  }
  const emergencyText = normalize(question).replace(/\b(emergency alerts?|alertas? de emergencia|alet dijans)\b/g, ' ');
  if (emergencyTerms.test(emergencyText)) {
    return json(card(emergency, emergencyCopy[language], 'emergency', 'catalog'));
  }
  const resource = pickResource(question, city);
  const fallback = () => card(contacts[city], fallbackCopy[language], 'unverified', 'catalog');
  const result = resource ? card(resource, resource.copy[language], 'verified', 'catalog') : fallback();
  if (demo === true && sponsorsAuthorized(request, env)) {
    const example = examples[city][language];
    const paraphrase = sponsorParaphrases.find((entry) =>
      entry.city === city && entry.language === language && entry.question === question.trim());
    const approved = paraphrase
      ? resources.find((entry) => entry.id === paraphrase.id && entry.city === city)
      : question.trim() === example ? resource : undefined;
    if (approved) {
      const sponsors = await runSponsors(approved, city, language, paraphrase?.question ?? example, env);
      if (sponsors.swarms === 'verified' && sponsors.prune === 'verified') {
        return json({ ...card(approved, approved.copy[language], 'verified', 'sponsors'), sponsors });
      }
      result.sponsors = sponsors;
    }
  }
  return json(result);
}

const worker = {
  async fetch(request, env = {}) {
    const { pathname } = new URL(request.url);
    if (pathname === '/api/health' && request.method === 'GET') {
      return json({ ok: true, resources: resources.length, sponsorDemo: sponsorsAuthorized(request, env) });
    }
    if (pathname === '/api/ask') {
      if (request.method !== 'POST') return new Response(null, { status: 405, headers: { Allow: 'POST' } });
      return ask(request, env);
    }
    if (Object.hasOwn(assets, pathname) && ['GET', 'HEAD'].includes(request.method)) {
      const [content, type] = assets[pathname];
      return new Response(request.method === 'HEAD' ? null : content, {
        headers: { ...safetyHeaders, 'Content-Type': type + '; charset=utf-8' },
      });
    }
    return json({ error: 'not_found' }, 404);
  },
};

import { secrets } from 'base44:runtime';
import { createClientFromRequest } from 'npm:@base44/sdk';


export default async function askCity(request) {
  const headers = new Headers(request.headers);
  headers.delete('Authorization');
  const env = {};
  try {
    const user = await createClientFromRequest(request).auth.me();
    if (user?.role === 'admin') {
      for (const key of ['SPONSOR_DEMO_TOKEN', 'SWARMS_API_KEY', 'SWARMS_MODEL', 'SWARMS_WORKFLOW', 'PRUNE_API_KEY', 'PRUNE_MODEL']) {
        env[key] = secrets.get(key);
      }
      if (env.SPONSOR_DEMO_TOKEN) headers.set('Authorization', 'Bearer ' + env.SPONSOR_DEMO_TOKEN);
    }
  } catch {
    // Anonymous users and auth outages can still use the public catalog.
  }
  const forwarded = new Request('https://askmycity.internal/api/ask', {
    method: request.method,
    headers,
    body: request.body,
    duplex: 'half',
  });
  return worker.fetch(forwarded, env);
}